<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>GAL界面</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Microsoft YaHei', Arial, sans-serif;
            overflow: auto;
            min-height: 100vh;
            background: #000;
        }

        /* 主容器 */
        .main-container {
            position: relative;
            width: 100vw;
            height: 150vw;
            min-height: 600px;
            display: flex;
            flex-direction: column;
            overflow: hidden; /* 隐藏超出立绘层范围的部分 */
        }

        /* 背景层 - 最底层，占满主容器 */
        .background-layer {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: 1;
            background: linear-gradient(180deg, #87CEEB 0%, #FFB6C1 100%);
            background-size: cover;
            background-position: center;
        }

        .background-layer img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        /* 立绘层 - 背景之上，占满主容器 */
        .character-layer {
            position: absolute;
            top: 30vh; /* 顶部距离容器顶部30% */
            left: 0;
            width: 100%;
            height: 50vh; /* 从30%到80%的高度范围，即50%的高度 */
            z-index: 2;
            display: flex;
            justify-content: center;
            align-items: flex-end; /* 角色底部对齐到这个区域的底部 */
            padding: 0 20px 0 20px;
        }

        .character {
            max-width: 100%; /* 适应容器宽度 */
            max-height: 100%; /* 适应容器高度 */
            opacity: 0;
            z-index: 10;
            transform: scale(1.5); /* 放大到150% */
            transform-origin: bottom center; /* 以底部中心为缩放原点 */
        }

        .character.active {
            opacity: 1;
        }

        /* 角色动画效果 */
        .character.jump {
            animation: jumpAnimation 0.6s ease-in-out;
        }

        @keyframes jumpAnimation {
            0% { transform: scale(1.5) translateY(0); }
            16.66% { transform: scale(1.5) translateY(-20px); }
            33.33% { transform: scale(1.5) translateY(0); }
            50% { transform: scale(1.5) translateY(-20px); }
            66.66% { transform: scale(1.5) translateY(0); }
            83.33% { transform: scale(1.5) translateY(-20px); }
            100% { transform: scale(1.5) translateY(0); }
        }

        .character.shake {
            animation: shakeAnimation 0.8s ease-in-out;
        }

        @keyframes shakeAnimation {
            0%, 100% { transform: scale(1.5) translateX(0); }
            10%, 30%, 50%, 70%, 90% { transform: scale(1.5) translateX(-5px); }
            20%, 40%, 60%, 80% { transform: scale(1.5) translateX(5px); }
        }

        .character.bounce {
            animation: bounceAnimation 1s ease-in-out;
        }

        @keyframes bounceAnimation {
            0%, 20%, 50%, 80%, 100% { transform: scale(1.5) translateY(0); }
            40% { transform: scale(1.5) translateY(-15px); }
            60% { transform: scale(1.5) translateY(-10px); }
        }

        .character img {
            width: 100%;
            height: auto;
            object-fit: contain;
            object-position: bottom;
            filter: drop-shadow(0 4px 8px rgba(0,0,0,0.3));
        }



        /* 对话栏层 - 占据主容器下面1/3，但点击区域扩展到整个屏幕高度 */
        .dialogue-layer {
            position: absolute;
            bottom: 0;
            left: 0;
            width: 100%;
            height: 100vh; /* 扩展到整个屏幕高度 */
            z-index: 3;
            background: linear-gradient(180deg, rgba(67,68,115,0) 0%, rgba(67,68,115,0) 66.67%, rgba(67,68,115,0.4) 86.67%, rgba(67,68,115,0.6) 100%);
            display: flex;
            flex-direction: column;
            justify-content: flex-end;
            padding: 20px 20px 80px 20px;
            cursor: pointer;
            pointer-events: auto;
            user-select: none; /* 禁用文本选中 */
            -webkit-user-select: none; /* Safari */
            -moz-user-select: none; /* Firefox */
            -ms-user-select: none; /* IE/Edge */
        }

        /* 对话框 */
        .dialogue-box {
            background: transparent;
            border-radius: 15px;
            padding: 20px;
            margin-bottom: 20px;
            box-shadow: none;
            backdrop-filter: none;
            border: none;
            position: relative;
