            }

            // 根据角色名和表情设置立绘
            setCharacterByName(characterName, expression) {
                const characterData = this.characterMap[characterName];
                if (characterData) {
                    const url = characterData[expression];
                    if (url) {
                        this.setCharacter(url, characterName);
                        console.log(`成功加载角色立绘: ${characterName} ${expression} -> ${url}`);
                    } else {
                        console.warn(`未找到表情: ${characterName} -> ${expression}`);
                        // 显示可用的表情列表
                        console.log(`${characterName} 可用表情:`, Object.keys(characterData));
                    }
                } else {
                    console.warn(`未找到角色: ${characterName}`);
                    // 显示可用的角色列表
                    console.log('可用角色:', Object.keys(this.characterMap));
                }
            }

            // 设置角色立绘、动作和对话的完整功能
            setCharacterWithActionAndDialogue(characterName, expression, action, dialogue) {
                const characterData = this.characterMap[characterName];
                if (characterData) {
                    const url = characterData[expression];
                    if (url) {
                        // 设置立绘
                        this.setCharacter(url, characterName);

                        // 执行动作
                        this.playCharacterAction(action);

                        // 显示对话
                        this.showDialogue(characterName, dialogue);

                        console.log(`完整设置角色: ${characterName} ${expression} 动作: ${action} 对话: ${dialogue}`);
                    } else {
                        console.warn(`未找到表情: ${characterName} -> ${expression}`);
                        console.log(`${characterName} 可用表情:`, Object.keys(characterData));
                    }
                } else {
                    console.warn(`未找到角色: ${characterName}`);
                    console.log('可用角色:', Object.keys(this.characterMap));
                }
            }

            // 播放角色动作
            playCharacterAction(action) {
                const characterElement = this.characterCenter;

                // 清除之前的动画类
                characterElement.classList.remove('jump', 'shake', 'bounce');

                // 动作映射表
                const actionMap = {
                    '跳': 'jump',
                    '震动': 'shake', 
                    '摇晃': 'shake',
                    '弹跳': 'bounce',
                    '跳跃': 'jump'
                };

                const animationClass = actionMap[action];
                if (animationClass) {
                    // 添加动画类
                    characterElement.classList.add(animationClass);

                    // 动画结束后移除类名，以便下次可以重新触发
                    setTimeout(() => {
                        characterElement.classList.remove(animationClass);
                    }, 1000); // 1秒后移除

                    console.log(`播放动作: ${action} -> ${animationClass}`);
                } else {
                    console.warn(`未知动作: ${action}`);
                    console.log('可用动作:', Object.keys(actionMap));
                }
            }

            // 显示对话
            showDialogue(character, text) {
                this.characterName.textContent = character || '系统';

                // 处理特殊格式的对话文本
                if (text) {
                    const formattedText = this.formatDialogueText(text);
                    this.dialogueText.innerHTML = formattedText;
                } else {
                    this.dialogueText.textContent = '';
                }
            }

            // 格式化对话文本，处理 *文字（小字）* 格式
            formatDialogueText(text) {
                // 匹配 *文字（小字）* 格式
                const dualTextRegex = /\*([^（]*?)（([^）]*?)）\*/g;

                let formattedText = text.replace(dualTextRegex, (match, mainText, smallText) => {
                    // 计算小字的字符间距，让它充分填充主文字的宽度
                    const letterSpacing = this.calculateLetterSpacing(mainText, smallText);

                    return `<span class="dual-text">
                        <span class="dual-text-small" style="letter-spacing: ${letterSpacing};">${smallText}</span>
                        <span class="dual-text-main">${mainText}</span>
                    </span>`;
                });

                return formattedText;
            }

            // 计算字符间距，让小字充分填充主文字的宽度
            calculateLetterSpacing(mainText, smallText) {
                // 如果小字只有1个字符，不需要间距
                if (smallText.length <= 1) {
                    return '0';
                }

                // 根据主文字和小字的长度比例计算间距
                // 这是一个近似计算，实际效果可能需要调整
                const mainLength = mainText.length;
                const smallLength = smallText.length;

                // 基础间距，可以根据需要调整
                let spacing = 0;

                if (mainLength > smallLength) {
                    // 主文字比小字长，需要增加小字间距
                    const ratio = mainLength / smallLength;
                    spacing = (ratio - 1) * 0.5; // 调整系数
                }

                // 限制最大间距，避免过于分散
                spacing = Math.min(spacing, 1.5);

                return `${spacing}em`;
            }

            // 设置背景
            setBackground(backgroundSrc) {
                if (backgroundSrc) {
                    this.backgroundLayer.innerHTML = `<img src="${backgroundSrc}" alt="背景图片">`;
                } else {
                    this.backgroundLayer.innerHTML = '';
                }
            }

            // 设置立绘
            setCharacter(characterSrc, characterName = '') {
                const characterElement = this.characterCenter;

                if (characterSrc) {
                    characterElement.innerHTML = `<img src="${characterSrc}" alt="角色立绘">`;
                    characterElement.classList.add('active');
                } else {
                    characterElement.innerHTML = '';
                    characterElement.classList.remove('active');
                }
            }

            // 显示当前对话
            showCurrentDialogue() {
                if (this.currentDialogueIndex >= this.dialogueQueue.length) {
                    // 所有对话都显示完了，但保持对话区显示
                    this.hideContinueIndicator();
                    console.log('所有对话显示完毕');
                    return;
                }

                const currentItem = this.dialogueQueue[this.currentDialogueIndex];

                if (currentItem.type === 'dialogue') {
                    this.setCharacterWithActionAndDialogue(
                        currentItem.characterName,
                        currentItem.expression,
                        currentItem.action,
                        currentItem.dialogue
                    );
                    // 若是首次到达该索引，则追加到记录
                    if (this.currentDialogueIndex >= this.appendedCount) {
                        this.appendToLog(currentItem.characterName, currentItem.expression, currentItem.action, currentItem.dialogue);
                        this.appendedCount = this.currentDialogueIndex + 1;
                    }
                } else if (currentItem.type === 'simple') {
                    this.showDialogue(currentItem.characterName, currentItem.dialogue);
                    if (this.currentDialogueIndex >= this.appendedCount) {
                        this.appendToLog(currentItem.characterName, '', '', currentItem.dialogue);
                        this.appendedCount = this.currentDialogueIndex + 1;
                    }
                }

                // 检查是否为最后一句对话，如果是则隐藏继续指示器
                if (this.currentDialogueIndex >= this.dialogueQueue.length - 1) {
                    this.hideContinueIndicator();
                } else {
                    this.showContinueIndicator();
                }
            }

            // 下一段对话
            nextDialogue() {
                if (this.dialogueQueue.length === 0) {
                    console.log('没有对话队列');
                    return;
                }

                this.currentDialogueIndex++;
                console.log(`切换到对话 ${this.currentDialogueIndex + 1}/${this.dialogueQueue.length}`);

                if (this.currentDialogueIndex >= this.dialogueQueue.length) {
                    // 所有对话都显示完了，但保持最后一句对话显示
                    this.currentDialogueIndex = this.dialogueQueue.length - 1; // 保持在最后一句
                    this.hideContinueIndicator();
                    console.log('所有对话显示完毕');
                    return;
                }

                this.showCurrentDialogue();
            }

            // 上一段对话
            previousDialogue() {
                if (this.dialogueQueue.length === 0) {
                    console.log('没有对话队列');
                    return;
                }

                if (this.currentDialogueIndex <= 0) {
                    console.log('已经是第一句对话');
                    return;
                }

                this.currentDialogueIndex--;
                console.log(`返回到对话 ${this.currentDialogueIndex + 1}/${this.dialogueQueue.length}`);

                this.showCurrentDialogue();

                // 如果不是最后一句，显示继续指示器
                if (this.currentDialogueIndex < this.dialogueQueue.length - 1) {
                    this.showContinueIndicator();
                }
            }

