        GALInterface.prototype.appendToLog = function(characterName, expression, action, dialogue) {
            const entry = {
                characterName,
                expression,
                action,
                dialogue
            };
            this.conversationLog.push(entry);
            this.renderLog();
        };

        GALInterface.prototype.renderLog = function() {
            if (!this.modalLog) return;
            const html = this.conversationLog.map((e, index) => {
                const avatar = this.resolveAvatar(e.characterName, e.expression);
                const textOnly = this.escapeHtml(e.dialogue || '');
                return `
                <div class="log-entry clickable" data-dialogue-index="${index}">
                    <div class="log-avatar-card">
                        ${avatar ? `<img class=\"log-avatar\" src=\"${avatar}\" alt=\"avatar\">` : ''}
                    </div>
                    <div class="log-bubble">
                        <div class="log-text">${textOnly}</div>
                    </div>
                </div>`;
            }).join('');
            this.modalLog.innerHTML = html || '<p style="text-align: center; color: #999; margin-top: 50px;">暂无对话记录</p>';

