        <div class="modal-content">
            <div class="modal-header">
                <h3 class="modal-title">对话记录</h3>
                <button class="modal-close-button" id="modalCloseButton"></button>
            </div>
            <div class="modal-body" id="modalBody">
                <div class="modal-log" id="modalLog"></div>
            </div>
        </div>
    </div>

    <script>
        class GALInterface {
            constructor() {
                this.dialogueBox = document.getElementById('dialogueBox');
                this.characterName = document.getElementById('characterName');
                this.dialogueText = document.getElementById('dialogueText');
                this.backgroundLayer = document.getElementById('backgroundLayer');
                this.characterCenter = document.getElementById('characterCenter');
                this.continueIndicator = document.getElementById('continueIndicator');

                // 弹窗相关元素
                this.menuButton = document.getElementById('menuButton');
                this.modalOverlay = document.getElementById('modalOverlay');
                this.modalCloseButton = document.getElementById('modalCloseButton');
                this.modalBody = document.getElementById('modalBody');
                this.modalLog = document.getElementById('modalLog');

                this.currentDialogue = '';
                this.currentCharacter = '';
                this.currentBackground = '';

                // 新增：对话队列管理
                this.dialogueQueue = [];
                this.currentDialogueIndex = 0;

                // 对话记录
                this.conversationLog = [];
                this.appendedCount = 0; // 已追加到记录的条目数量

                this.init();
            }

            init() {
                // 对话层点击事件监听（扩展到整个屏幕）
                this.dialogueLayer = document.getElementById('dialogueLayer');
                this.dialogueLayer.addEventListener('click', (e) => {
                    this.handleDialogueClick(e);
                });

                // 对话层触摸事件监听（移动端）
                this.dialogueLayer.addEventListener('touchend', (e) => {
                    e.preventDefault();
                    this.handleDialogueClick(e);
                });

                // MENU按钮点击事件
                this.menuButton.addEventListener('click', (e) => {
                    e.stopPropagation();
                    this.showModal();
                });

                // 关闭按钮点击事件
                this.modalCloseButton.addEventListener('click', () => {
                    this.hideModal();
                });

                // 点击弹窗外部关闭
                this.modalOverlay.addEventListener('click', (e) => {
                    if (e.target === this.modalOverlay) {
                        this.hideModal();
                    }
                });

                // 初始化window.updateContent函数
                this.setupUpdateContent();

                // 确保对话区始终显示
                this.showDialogue('系统', '点击屏幕开始游戏...');
            }

            // 处理对话层点击事件
            handleDialogueClick(e) {
                const rect = this.dialogueLayer.getBoundingClientRect();
                const clickX = e.clientX || (e.touches && e.touches[0] ? e.touches[0].clientX : e.changedTouches[0].clientX);
                const relativeX = clickX - rect.left;
                const layerWidth = rect.width;

                // 判断点击位置：左边1/3为上一句，右边2/3为下一句
                if (relativeX < layerWidth / 3) {
                    // 点击左边1/3区域，返回上一句
                    this.previousDialogue();
                } else {
                    // 点击右边2/3区域，进入下一句
                    this.nextDialogue();
                }
            }

            // 设置从window.updateContent提取文本的函数
            setupUpdateContent() {
                window.updateContent = (content) => {
                    this.processContent(content);
                };

                // 初始化背景图片映射表
                this.initBackgroundMap();

                // 初始化角色立绘映射表
                this.initCharacterMap();

                // 初始化头像映射表
                this.initAvatarMap();
            }

