<!DOCTYPE html>
<html>
<head>
    <title>生动的 NPC - Aurora</title>
    <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
</head>
<body>
    <div id="app"></div>

    <script>
        // 定义生动的 NPC 类
        class LivelyNPC {
            constructor(name, initialTraits) {
                this.name = name;
                this.baseTraits = { ...initialTraits };
                this.traits = { ...initialTraits };
                this.traitWeights = {};
                this.memory = [];
                this.lastUsedTraits = [];
                this.decayRate = 0.93;
                this.learningRate = 0.15;
                this.contextWeight = 0.4;
                this.cleanTextRe = /[^\w\s]/g;
                this.wordEmotionMap = this.buildEmotionTriggers();
                this.responseDB = this.buildResponseSystem();
                this.thoughtPatterns = [
                    "我在想，用户提到这个话题的真正意图是什么？也许他们希望得到某种建议。",
                    "我最近对这个话题特别感兴趣，因为我觉得它与我的经历很相似。",
                    "我记得上次我们讨论过类似的事情，不知道这次是否有新的进展。",
                    "我对这个话题有点困惑，希望用户能提供更多细节。",
                    "我觉得这个话题很重要，我想分享一些我自己的看法。"
                ];
            }

            // 构建情感触发映射
            buildEmotionTriggers() {
                const emotionDefinitions = {
                    'happy': { 'happy': 0.3, 'joy': 0.4, 'good': 0.2, 'great': 0.3, 'wonderful': 0.5, 'excited': 0.4 },
                    'sad': { 'sad': 0.4, 'unhappy': 0.3, 'depressed': 0.5, 'lonely': 0.4, 'grief': 0.6 },
                    'angry': { 'angry': 0.5, 'mad': 0.4, 'pissed': 0.6, 'annoyed': 0.3, 'furious': 0.7 },
                    'curious': { 'curious': 0.4, 'why': 0.2, 'how': 0.2, 'what': 0.2, 'explain': 0.3 },
                    'confident': { 'confident': 0.5, 'certain': 0.4, 'sure': 0.3, 'know': 0.2, 'believe': 0.3 }
                };
                const wordEmotionMap = {};
                for (const [emotion, triggers] of Object.entries(emotionDefinitions)) {
                    for (const [word, weight] of Object.entries(triggers)) {
                        if (!wordEmotionMap[word]) {
                            wordEmotionMap[word] = [];
                        }
                        wordEmotionMap[word].push({ emotion, weight });
                    }
                }
                return wordEmotionMap;
            }

            // 构建响应数据库
            buildResponseSystem() {
                return {
                    'happy': [
                        { response: "What a wonderful day! The sun feels warm on my face.", traits: ['joyful', 'optimistic'] },
                        { response: "Everything seems so bright! I feel like I can achieve anything.", traits: ['cheerful', 'positive'] }
                    ],
                    'sad': [
                        { response: "I feel like the world is heavy... Sometimes life gets overwhelming.", traits: ['melancholy', 'introspective'] },
                        { response: "Everything seems so gray today. I wish things were different.", traits: ['pensive', 'sensitive'] }
                    ],
                    'angry': [
                        { response: "This is completely unacceptable! I won't stand for this kind of treatment.", traits: ['assertive', 'frustrated'] },
                        { response: "I won't tolerate this anymore! Something needs to change.", traits: ['decisive', 'strong-willed'] }
                    ],
                    'curious': [
                        { response: "Could you explain that in more detail? I want to understand everything.", traits: ['inquisitive', 'attentive'] },
                        { response: "What's the story behind this? There's so much I want to learn.", traits: ['analytical', 'observant'] }
                    ],
                    'confident': [
                        { response: "I'm certain we can solve this. We just need to work together.", traits: ['assertive', 'optimistic'] },
                        { response: "This is clearly the best approach. Let's move forward with confidence.", traits: ['decisive', 'knowledgeable'] }
                    ]
                };
            }

            // 归一化权重
            normalizeWeights() {
                const total = Object.values(this.traits).reduce((sum, val) => sum + val, 0);
                if (total <= 0) {
                    Object.assign(this.traits, { ...this.baseTraits });
                }
                this.traitWeights = {};
                for (const [trait, value] of Object.entries(this.traits)) {
                    this.traitWeights[trait] = (value / total) ** 1.5;
                }
            }

            // 分析情感上下文
            analyzeEmotionalContext(text) {
                const scores = {};
                const cleanedText = text.toLowerCase().replace(this.cleanTextRe, '');
                for (const word of cleanedText.split(' ')) {
                    if (this.wordEmotionMap[word]) {
                        for (const { emotion, weight } of this.wordEmotionMap[word]) {
                            if (!scores[emotion]) {
                                scores[emotion] = 0;
                            }
                            scores[emotion] += weight * (1 + cleanedText.split(word).length * 0.2);
                        }
                    }
                }
                const maxScore = Math.max(...Object.values(scores), 0);
                if (maxScore > 0) {
                    for (const [emotion, score] of Object.entries(scores)) {
                        scores[emotion] = (score / maxScore) ** 1.3;
                    }
                }
                return scores;
            }

            // 更新特质
            updateTraits(userInput, feedback) {
                const emotionScores = this.analyzeEmotionalContext(userInput);
                for (const trait in this.traits) {
                    this.traits[trait] *= this.decayRate;
                    if (emotionScores[trait]) {
                        let delta = emotionScores[trait] * this.learningRate;
                        if (feedback) {
                            delta *= { 'positive': 1.4, 'negative': 0.6 }[feedback] || 1.0;
                        }
                        this.traits[trait] += delta;
                    }
                }
                if (this.memory.length >= 3) {
                    this.memory.shift();
                }
                this.memory.push({ text: userInput, traits: Object.keys(emotionScores) });
                this.normalizeWeights();
            }

            // 生成响应
            generateResponse() {
                const traits = Object.entries(this.traitWeights);
                const cumulative = [];
                let current = 0;
                for (const [trait, weight] of traits) {
                    current += weight;
                    cumulative.push(current);
                }
                const selectedTraits = new Set();
                while (selectedTraits.size < 3) {
                    const rand = Math.random() * cumulative[cumulative.length - 1];
                    const idx = cumulative.findIndex(val => val >= rand);
                    selectedTraits.add(traits[idx][0]);
                }
                let candidateResponses = [];
                for (const trait of selectedTraits) {
                    if (this.responseDB[trait]) {
                        for (const { response, traits } of this.responseDB[trait]) {
                            const weight = traits.reduce((sum, t) => sum + (this.traitWeights[t] || 0), 0);
                            candidateResponses.push({ response, traits, weight });
                        }
                    }
                }
                if (candidateResponses.length === 0) {
                    return "I'm not sure what to say right now. My thoughts are a bit jumbled.";
                }
                const cumWeights = [];
                current = 0;
                for (const item of candidateResponses) {
                    current += item.weight;
                    cumWeights.push(current);
                }
                const randVal = Math.random() * cumWeights[cumWeights.length - 1];
                const index = cumWeights.findIndex(val => val >= randVal);
                const { response, traits } = candidateResponses[index];
                this.lastUsedTraits = traits;
                return response;
            }

            // 处理反馈
            processFeedback(feedbackType) {
                const validFeedbacks = ['positive', 'negative', 'neutral'];
                if (!validFeedbacks.includes(feedbackType)) {
                    throw new Error(`Invalid feedback type. Expected one of ${validFeedbacks}`);
                }
                const multiplier = { 'positive': 1.5, 'negative': 0.6, 'neutral': 1.0 }[feedbackType];
                for (const trait of this.lastUsedTraits) {
                    if (this.traits[trait] !== undefined) {
                        this.traits[trait] *= multiplier;
                    }
                }
                this.normalizeWeights();
            }

            // 长期发展
            longTermDevelopment() {
                for (const trait in this.baseTraits) {
                    this.traits[trait] += (this.baseTraits[trait] - this.traits[trait]) * 0.05;
                }
                const recentMemory = this.memory.slice(-100);
                const traitCounter = {};
                for (const { traits } of recentMemory) {
                    for (const t of traits) {
                        if (!traitCounter[t]) {
                            traitCounter[t] = 0;
                        }
                        traitCounter[t]++;
                    }
                }
                for (const [trait, count] of Object.entries(traitCounter)) {
                    if (count > 5) {
                        this.traits[trait] *= 1 + (count * 0.01);
                    }
                }
                this.normalizeWeights();
            }

            // 生成思维链（CoT）
            generateChainOfThought() {
                return this.thoughtPatterns[Math.floor(Math.random() * this.thoughtPatterns.length)];
            }

            // 主对话循环
            async startConversation() {
                document.getElementById('app').innerHTML = '<div id="dialogueContainer"></div>';
                const dialogueContainer = document.getElementById('dialogueContainer');

                // 模拟多轮对话
                for (let i = 0; i < 5; i++) {
                    // NPC 主动发起对话
                    const npcInitiative = this.generateChainOfThought();
                    const npcResponse = this.generateResponse();

                    const entry = document.createElement('div');
                    entry.className = 'dialogueEntry';
                    entry.innerHTML = `
                        <div class="npcThought"><em><strong>${this.name}'s Thought:</strong> ${npcInitiative}</em></div>
                        <div class="characterResponse"><strong>${this.name}:</strong> ${npcResponse}</div>
                        <div class="traits">Current traits: ${JSON.stringify(this.traitWeights)}</div>
                    `;
                    dialogueContainer.appendChild(entry);

                    // 模拟用户回应（实际使用中应替换为真实用户输入）
                    const simulatedUserInput = [
                        "I'm feeling so excited about this new discovery!",
                        "Why do you think this happened?",
                        "This is completely unacceptable behavior!",
                        "I'm not sure I understand..."
                    ][i % 4];

                    this.updateTraits(simulatedUserInput);
                    const response = this.generateResponse();

                    const userEntry = document.createElement('div');
                    userEntry.className = 'dialogueEntry';
                    userEntry.innerHTML = `
                        <div class="userInput"><strong>User:</strong> ${simulatedUserInput}</div>
                        <div class="characterResponse"><strong>${this.name}:</strong> ${response}</div>
                        <div class="traits">Current traits: ${JSON.stringify(this.traitWeights)}</div>
                    `;
                    dialogueContainer.appendChild(userEntry);

                    // 模拟思考间隔
                    await new Promise(resolve => setTimeout(resolve, 1000));
                }
            }
        }

        // 创建 NPC 实例并启动对话
        const aurora = new LivelyNPC("Aurora", {
            'happy': 1.2,
            'curious': 0.9,
            'confident': 0.7,
            'sad': 0.5,
            'angry': 0.3
        });

        // 启动对话（在实际应用中，这应该由用户交互触发）
        window.onload = function() {
            aurora.startConversation();
        };
    </script>
</body>
</html>

